pub const info_v1_expectation: Expectation = Expectation { interface_id_lo: 0x41434f31, interface_id_hi: 0x52344f53, abi_major: 1, min_revision: 1, required_size: 40, known_required_flags: 0 };
pub const info_v1_export_name: &str = "INFO_V1";
pub type InfoV1_get_infoFn = unsafe extern "C" fn(r#output: *mut R4AcoInfo, r#output_bytes: u32) -> i32;
/// Independent immutable library identity, append-only interface.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct InfoV1 {
    pub header: InterfaceHeader,
    pub r#get_info: Option<InfoV1_get_infoFn>,
}
const _: () = {
    assert!(core::mem::size_of::<InfoV1>() == 40);
    assert!(core::mem::align_of::<InfoV1>() == 8);
    assert!(core::mem::offset_of!(InfoV1, r#get_info) == 32);
};

pub struct InfoV1Client<'a> { interface: Interface<'a> }
impl<'a> InfoV1Client<'a> {
    pub fn init(app: &'a App<'_>) -> Result<Self, Error> {
        let interface = Interface::new(app, MODULE_NAME, info_v1_export_name, info_v1_expectation)?;
        Self::checked(interface)
    }
    pub fn optional(app: &'a App<'_>) -> Result<Option<Self>, Error> {
        Interface::optional(app, MODULE_NAME, info_v1_export_name, info_v1_expectation)?.map(Self::checked).transpose()
    }
    fn checked(interface: Interface<'a>) -> Result<Self, Error> {
        if interface.slot_address(32).is_none() { return Err(Error::MissingSlot); }
        Ok(Self { interface })
    }
    /// Return source/build identity. Capability bit0 reports CPU shader compilation only. Source compatibility and compiler availability never admit a physical GPU.
    /// # Safety
    /// No retained memory, allocation, hardware access or shared mutable state.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// output: output, caller_owned, lifetime call, nullable=false.
    /// output_bytes: value, none, lifetime none, nullable=false.
    pub unsafe fn r#get_info(&self, r#output: *mut R4AcoInfo, r#output_bytes: u32) -> i32 {
        let function: InfoV1_get_infoFn = unsafe { self.interface.function(32) }.expect("admitted R4L slot");
        unsafe { function(r#output, r#output_bytes) }
    }
}

pub const compiler_v1_expectation: Expectation = Expectation { interface_id_lo: 0x41434f32, interface_id_hi: 0x52344f53, abi_major: 1, min_revision: 1, required_size: 56, known_required_flags: 0 };
pub const compiler_v1_export_name: &str = "COMPILER_V1";
pub type CompilerV1_compileFn = unsafe extern "C" fn(r#runtime: *const R4AcoRuntime, r#request: *const R4AcoRequest, r#output: *mut R4AcoBinary) -> i32;
pub type CompilerV1_cache_writeFn = unsafe extern "C" fn(r#key: *const R4AcoCacheKey, r#binary: *const R4AcoBinary, r#code: *const u8, r#code_length: u64, r#bytes: *mut u8, r#capacity: u64, r#written: *mut u64) -> i32;
pub type CompilerV1_cache_readFn = unsafe extern "C" fn(r#key: *const R4AcoCacheKey, r#bytes: *const u8, r#length: u64, r#output: *mut R4AcoBinary, r#code: *mut u8, r#capacity: u64) -> i32;
/// Pinned Mesa26.2.2 SPIR-V/NIR/ACO for Picasso/Raven2 native buffer ABI1 and combined 2D texture ABI2. Vertex, fragment, compute. CPU compilation only.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct CompilerV1 {
    pub header: InterfaceHeader,
    pub r#compile: Option<CompilerV1_compileFn>,
    pub r#cache_write: Option<CompilerV1_cache_writeFn>,
    pub r#cache_read: Option<CompilerV1_cache_readFn>,
}
const _: () = {
    assert!(core::mem::size_of::<CompilerV1>() == 56);
    assert!(core::mem::align_of::<CompilerV1>() == 8);
    assert!(core::mem::offset_of!(CompilerV1, r#compile) == 32);
    assert!(core::mem::offset_of!(CompilerV1, r#cache_write) == 40);
    assert!(core::mem::offset_of!(CompilerV1, r#cache_read) == 48);
};

pub struct CompilerV1Client<'a> { interface: Interface<'a> }
impl<'a> CompilerV1Client<'a> {
    pub fn init(app: &'a App<'_>) -> Result<Self, Error> {
        let interface = Interface::new(app, MODULE_NAME, compiler_v1_export_name, compiler_v1_expectation)?;
        Self::checked(interface)
    }
    pub fn optional(app: &'a App<'_>) -> Result<Option<Self>, Error> {
        Interface::optional(app, MODULE_NAME, compiler_v1_export_name, compiler_v1_expectation)?.map(Self::checked).transpose()
    }
    fn checked(interface: Interface<'a>) -> Result<Self, Error> {
        if interface.slot_address(32).is_none() { return Err(Error::MissingSlot); }
        if interface.slot_address(40).is_none() { return Err(Error::MissingSlot); }
        if interface.slot_address(48).is_none() { return Err(Error::MissingSlot); }
        Ok(Self { interface })
    }
    /// Blocking CPU compilation exclusively on an isolated worker, never a frame/paint/IRQ callback. Busy returns immediately. Abort/OOM discards the entire private compilation allocation graph and terminates that worker; joining remains the caller's responsibility.
    /// # Safety
    /// Caller-owned inputs and buffers stay alive through worker join. The library retains no pointer after normal completion or its abort callback. All callbacks belong to the admitted job.
    /// Blocking: blocking; threading: thread_safe; reentrancy: not_reentrant.
    /// runtime: input, borrowed, lifetime call, nullable=false.
    /// request: input, borrowed, lifetime call, nullable=false.
    /// output: output, caller_owned, lifetime call, nullable=false.
    pub unsafe fn r#compile(&self, r#runtime: *const R4AcoRuntime, r#request: *const R4AcoRequest, r#output: *mut R4AcoBinary) -> i32 {
        let function: CompilerV1_compileFn = unsafe { self.interface.function(32) }.expect("admitted R4L slot");
        unsafe { function(r#runtime, r#request, r#output) }
    }
    /// Serialize explicit little-endian scalar metadata and original ACO output into caller storage; checksummed and compiler-bound. No filesystem access. Outputs unchanged on error.
    /// # Safety
    /// No retained pointers, allocation, filesystem or device access.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// key: input, borrowed, lifetime call, nullable=false.
    /// binary: input, borrowed, lifetime call, nullable=false.
    /// code: input, borrowed, lifetime call, nullable=false.
    /// code_length: value, none, lifetime none, nullable=false.
    /// bytes: output, caller_owned, lifetime call, nullable=false.
    /// capacity: value, none, lifetime none, nullable=false.
    /// written: output, caller_owned, lifetime call, nullable=false.
    pub unsafe fn r#cache_write(&self, r#key: *const R4AcoCacheKey, r#binary: *const R4AcoBinary, r#code: *const u8, r#code_length: u64, r#bytes: *mut u8, r#capacity: u64, r#written: *mut u64) -> i32 {
        let function: CompilerV1_cache_writeFn = unsafe { self.interface.function(40) }.expect("admitted R4L slot");
        unsafe { function(r#key, r#binary, r#code, r#code_length, r#bytes, r#capacity, r#written) }
    }
    /// Validate the complete cache identity, metadata and digest before publishing any code. Corruption, old compiler, wrong ASIC/layout/epoch are cache misses; never GPU submissions.
    /// # Safety
    /// No retained pointers, allocation, filesystem or device access.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// key: input, borrowed, lifetime call, nullable=false.
    /// bytes: input, borrowed, lifetime call, nullable=false.
    /// length: value, none, lifetime none, nullable=false.
    /// output: output, caller_owned, lifetime call, nullable=false.
    /// code: output, caller_owned, lifetime call, nullable=false.
    /// capacity: value, none, lifetime none, nullable=false.
    pub unsafe fn r#cache_read(&self, r#key: *const R4AcoCacheKey, r#bytes: *const u8, r#length: u64, r#output: *mut R4AcoBinary, r#code: *mut u8, r#capacity: u64) -> i32 {
        let function: CompilerV1_cache_readFn = unsafe { self.interface.function(48) }.expect("admitted R4L slot");
        unsafe { function(r#key, r#bytes, r#length, r#output, r#code, r#capacity) }
    }
}
